import {backend} from './backend.js';
import {escape as e,download} from './store.js';
let ui;
export function initDownloads(callbacks){ui=callbacks;}
export function requestDownload(resource,{personalNotes=''}={}){
 ui.modal('Enter access code',`<p class="muted">Enter your access code to download “${e(resource.title)}”.</p><form id="download-form"><label for="access-code">Access code</label><input id="access-code" name="code" type="password" autocomplete="off" required><p id="download-status" class="muted" role="status"></p><div class="actions"><button class="btn primary" id="download-submit">Download</button><button class="btn" type="button" id="download-cancel">Cancel</button></div></form>`);
 document.querySelector('#download-cancel').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#download-form').onsubmit=async event=>{event.preventDefault();const submit=document.querySelector('#download-submit'),status=document.querySelector('#download-status');submit.disabled=true;try{status.textContent='Checking access code…';const local=!resource.lexamah_cloud;const result=await backend.protectedDownload(local?'local':resource.resource_type||'materials',resource.id,new FormData(event.target).get('code'));if(!result.authorized)throw new Error('Access code could not be verified.');if(local){download(`${String(resource.title).replace(/[^a-z0-9]/gi,'-')}.txt`,`${resource.title}\n\n${resource.body||resource.description||''}\n\nPERSONAL NOTES\n${personalNotes}`);}else if(result.url){const a=document.createElement('a');a.href=result.url;a.download=result.fileName||'resource';a.target='_blank';a.rel='noopener';a.click();}else{download(result.fileName||'lecture-notes.txt',result.text||'');}document.querySelector('#dialog').close();ui.toast('Your download is ready.');}catch(err){status.textContent=err.message;}finally{submit.disabled=false;}};
}
